func _on_health_changed(hp: float, _max_hp: float) -> void:
	var on := _alive and hp > 0.0 and hp <= THRESHOLD
	if on:
		smoke.amount_ratio = ratio_for(hp)
	if smoke.emitting != on:
		smoke.emitting = on


func _on_died() -> void:
	_alive = false
	smoke.emitting = false

